190	}
191	
192	// resumeByCheckpointID restores the session(s) recorded in a specific committed
193	// checkpoint and prints the resume command(s). Unlike resumeFromCurrentBranch it
194	// does not search branch history — the caller already knows which checkpoint to
195	// resume, so two sessions on the same branch resume independently.
196	func resumeByCheckpointID(ctx context.Context, w, errW io.Writer, checkpointID id.CheckpointID, force bool) error {
197		sessions, err := restoreByCheckpointID(ctx, w, errW, checkpointID, force)
198		if err != nil {
199			return err
200		}
201		if err := ensureSessionsRestored(sessions, force); err != nil {
202			return err
203		}
204		if len(sessions) == 0 {
205			return nil
206		}
207		return continueSessionRestoredSessions(ctx, w, sessions)
208	}
209	
210	func restoreByCheckpointID(ctx context.Context, w, errW io.Writer, checkpointID id.CheckpointID, force bool) ([]strategy.RestoredSession, error) {
211		if checkpointID.IsEmpty() {
212			return nil, errors.New("no checkpoint to resume")
213		}
214	
215		repo, err := openRepository(ctx)
216		if err != nil {
217			return nil, fmt.Errorf("not a git repository: %w", err)
218		}
219		defer repo.Close()
220	
221		stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: FetchBlobsByHash, RefFetcher: FetchCheckpointRef})
222		if err != nil {
223			return nil, fmt.Errorf("open checkpoint store: %w", err)
224		}
225		store := stores.Persistent
226		refs := stores.Refs()
227		if refs.ReadBootstrappableFromOrigin() {
228			promoteRemoteTrackingPrimary(ctx, repo, refs)
229		}
230	
231		metadata, err := readCheckpointInfoFromStore(ctx, store, checkpointID)
232		if err != nil {
233			logging.Debug(ctx, "resume by checkpoint: metadata read failed, checking remote",
234				slog.String("checkpoint_id", checkpointID.String()),
235				slog.String("error", err.Error()),
236			)
237			return checkRemoteMetadata(ctx, w, errW, checkpointID, stores.Refs())
238		}
239	
240		return restoreResumeSessions(ctx, w, errW, metadata, force)
241	}
242	
243	func resumeFromCurrentBranch(ctx context.Context, w, errW io.Writer, branchName string, force bool) error {
244		sessions, err := restoreFromCurrentBranch(ctx, w, errW, branchName, force, true)
245		if err != nil {
246			return err
247		}
248		if err := ensureSessionsRestored(sessions, force); err != nil {
249			return err
250		}
251		if len(sessions) == 0 {
252			return nil
253		}
254		return continueSessionRestoredSessions(ctx, w, sessions)
255	}
256	
257	// ensureSessionsRestored enforces the shared resume contract: zero restored
258	// sessions is a failure for scripted callers. When prompts were possible the
259	// zero is treated as a decline and exits 0 — the guard cannot distinguish a
260	// genuine empty restore there (the user saw the restore messages).
261	func ensureSessionsRestored(sessions []strategy.RestoredSession, force bool) error {
262		if len(sessions) > 0 {
263			return nil
264		}
265		if !force && interactive.CanPromptInteractively() {
266			return nil
267		}
268		return &ResumeNoSessionsRestoredError{}
269	}
270	
271	func continueSessionRestoredSessions(ctx context.Context, w io.Writer, sessions []strategy.RestoredSession) error {
272		return continueRestoredSessions(ctx, w, sessions, restoredSessionContinueOptions{
273			CanPrompt:     interactive.CanPromptInteractively(),
274			PromptSession: promptTrailRestoredSession,
275			Launch:        launchTrailRestoredSession,
276			Display:       displayRestoredSessions,
277		})
278	}
279	
280	// restoreFromCurrentBranch restores the latest checkpoint's sessions on
281	// branchName. allowPrompts=false suppresses the older-checkpoint confirmation
282	// even on a real terminal (the --json path, whose stdout must carry only
283	// JSON) without implying --force's log-overwrite semantics.
284	func restoreFromCurrentBranch(ctx context.Context, w, errW io.Writer, branchName string, force, allowPrompts bool) ([]strategy.RestoredSession, error) {
285		logCtx := logging.WithComponent(ctx, "resume")
286	
287		repo, err := openRepository(ctx)
288		if err != nil {
289			return nil, fmt.Errorf("not a git repository: %w", err)
290		}
291		defer repo.Close()
292	
293		// Find a commit with an Entire-Checkpoint trailer, looking at branch-only commits
294		result, err := findBranchCheckpoints(repo, branchName)
295		if err != nil {
296			return nil, err
297		}
298		if len(result.checkpointIDs) == 0 {
299			return nil, &ResumeNoCheckpointError{Branch: branchName}
