121	// refs/remotes/origin/HEAD) cannot be misrouted into the branch flow. A
122	// lookup swapped in by the remote fallback is closed here; the caller keeps
123	// ownership of the lookup it passed in.
124	func resumeAutoTarget(ctx context.Context, cmd *cobra.Command, lookup *explainCheckpointLookup, target string, force bool) error {
