131			}
132		}
133	
134		if branchExistsLocally(lookup.repo, target) {
135			return runResume(ctx, cmd, target, force)
136		}
137	
138		if shapedLikeCheckpoint {
139			matches, fresh := matchCheckpointPrefixWithRemoteFallback(ctx, cmd.ErrOrStderr(), lookup, target)
140			if fresh != lookup {
141				defer func() { _ = fresh.Close() }()
142				lookup = fresh
143			}
144			if len(matches) > 0 {
145				return resumeMatchedCheckpoints(ctx, cmd, lookup, target, matches, force)
146			}
147		}
148	
149		err := resumeCommitTarget(ctx, cmd, lookup, target, force)
150		if errors.Is(err, errNoResumeCommit) {
151			if remoteExists, remoteErr := BranchExistsOnRemote(ctx, target); remoteErr == nil && remoteExists {
