159	func resumeMatchedCheckpoints(ctx context.Context, cmd *cobra.Command, lookup *explainCheckpointLookup, prefix string, matches []id.CheckpointID, force bool) error {
160		switch len(matches) {
161		case 0:
162			return fmt.Errorf("no committed checkpoint matched %q\nHint: run 'entire checkpoint list' to see available checkpoints", prefix)
163		case 1:
164			return resumeResolvedCheckpoint(ctx, cmd, lookup, matches[0], force)
165		default:
