214	// branch containing it (at the branch's current tip) when one exists, points
215	// at the owning worktree when that branch is checked out elsewhere, and falls
216	// back to restoring session logs in place when no local branch contains it.
217	func resumeResolvedCheckpoint(ctx context.Context, cmd *cobra.Command, lookup *explainCheckpointLookup, cpID id.CheckpointID, force bool) error {
