224		}
225		if otherPath, ok := branchCheckedOutElsewhere(ctx, branch); ok {
226			// Guidance on stderr, typed silent error for the exit code: nothing
227			// was resumed, and scripted callers must be able to detect that.
228			fmt.Fprintf(cmd.ErrOrStderr(), "Branch %q is already checked out at %s.\nResume this checkpoint from that worktree:\n\n  cd %s && entire checkpoint resume %s\n",
229				branch, otherPath, shellQuote(otherPath), cpID)
230			return NewSilentError(&ResumeWorktreeClashError{Branch: branch, WorktreePath: otherPath})
231		}
232		return resumeSessionOnBranch(ctx, cmd, branch, cpID, force)
233	}
