241		// newest-first; see checkpoint.sortCheckpointInfosByRecency.
242		entries := lookup.committed
243		if len(entries) > checkpointResumePickerLimit {
244			entries = entries[:checkpointResumePickerLimit]
245		}
246		if len(entries) == 0 {
247			fmt.Fprintln(w, "No committed checkpoints found.")
248			fmt.Fprintln(w, "Checkpoints are created when you commit during an agent session.")
249			return nil
250		}
251		branchIndex := buildCheckpointBranchIndex(lookup.repo)
252	
253		if !interactive.CanPromptInteractively() {
254			printCheckpointResumeList(w, entries, branchIndex)
255			return nil
256		}
257	
258		selected, ok, err := promptCheckpointSelection(ctx, entries, branchIndex)
259		if err != nil {
260			return err
261		}
262		if !ok {
263			fmt.Fprintln(w, "Resume cancelled.")
264			return nil
265		}
266		return resumeResolvedCheckpoint(ctx, cmd, lookup, selected, force)
267	}
