269	func printCheckpointResumeList(w io.Writer, entries []checkpoint.CheckpointInfo, branchIndex map[string]string) {
270		fmt.Fprintf(w, "Recent checkpoints (newest first, up to %d):\n\n", checkpointResumePickerLimit)
271		for _, e := range entries {
272			branch := branchIndex[e.CheckpointID.String()]
273			if branch == "" {
274				branch = "-"
275			}
276			fmt.Fprintf(w, "  %s  %s  %s  %s\n", e.CheckpointID, e.CreatedAt.Local().Format("2006-01-02 15:04"), branch, checkpointAgentLabel(e))
277		}
278		fmt.Fprintln(w, "\nResume one with: entire checkpoint resume <checkpoint-id>")
279	}
