281	func promptCheckpointSelection(ctx context.Context, entries []checkpoint.CheckpointInfo, branchIndex map[string]string) (id.CheckpointID, bool, error) {
282		options := make([]huh.Option[string], 0, len(entries)+1)
283		for _, e := range entries {
284			options = append(options, huh.NewOption(checkpointResumeOptionLabel(e, branchIndex), e.CheckpointID.String()))
285		}
286		options = append(options, huh.NewOption("Cancel", resumePickerCancel))
287	
288		var choice string
289		form := NewAccessibleForm(huh.NewGroup(
290			huh.NewSelect[string]().
291				Title("Resume which checkpoint?").
292				Description("Checks out the checkpoint's branch (when one contains it) and restores the session log.").
293				Options(options...).
294				Value(&choice),
295		))
296		if err := form.RunWithContext(ctx); err != nil {
297			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
298				return "", false, nil
299			}
300			return "", false, fmt.Errorf("failed to pick checkpoint: %w", err)
301		}
302		if choice == resumePickerCancel {
303			return "", false, nil
304		}
305		return id.CheckpointID(choice), true, nil
306	}
307	
308	func checkpointResumeOptionLabel(e checkpoint.CheckpointInfo, branchIndex map[string]string) string {
309		branch := branchIndex[e.CheckpointID.String()]
310		if branch == "" {
311			branch = "no local branch"
312		}
313		return fmt.Sprintf("%s · %s · %s · %s", e.CheckpointID.DisplayShort(), branch, checkpointAgentLabel(e), timeAgo(e.CreatedAt))
314	}
315	
316	func checkpointAgentLabel(e checkpoint.CheckpointInfo) string {
317		if e.Agent == "" {
318			return unknownAgentLabel
319		}
320		return string(e.Agent)
321	}
